pub fn test(text: &str, operation: &str) -> Option<bool> {
    let mask = match operation {
        "isalpha" => 1, "isdecimal" => 2, "isdigit" => 4,
        "isnumeric" => 8, "isspace" => 16, "isprintable" => 32,
        "isalnum" => 1 | 8, _ => 0,
    };
    if mask != 0 {
        return Some((operation == "isprintable" || !text.is_empty()) && text.chars().all(|c| properties(c) & mask != 0));
    }
    Some(match operation {
        "isascii" => text.is_ascii(),
        "isidentifier" => !text.is_empty() && text.chars().enumerate().all(|(i, c)| properties(c) & if i == 0 { 64 } else { 128 } != 0),
        "islower" => text.chars().any(|c| properties(c) & 256 != 0) && text.chars().all(|c| properties(c) & (512 | 1024) == 0),
        "isupper" => text.chars().any(|c| properties(c) & 512 != 0) && text.chars().all(|c| properties(c) & (256 | 1024) == 0),
        _ => return None,
    })
}

pub fn change(text: &str, operation: &str) -> Option<String> {
    let mode = match operation { "upper" => 0, "lower" => 1, "casefold" => 2, "title" | "capitalize" => 3, "swapcase" => 4, _ => return None };
    if mode == 1 { return Some(text.to_lowercase()); }
    let mut out = String::new();
    let mut previous = false;
    for (index, c) in text.chars().enumerate() {
        let flags = properties(c);
        let choice = match mode {
            3 => if (operation == "capitalize" && index == 0) || (operation == "title" && !previous) { 3 } else { 1 },
            4 => if flags & 256 != 0 { 0 } else if flags & 512 != 0 { 1 } else { out.push(c); continue },
            n => n,
        };
        out.push_str(&mapped(c, choice));
        previous = flags & (256 | 512 | 1024) != 0;
    }
    Some(out)
}

pub fn quoted(text: &str, ascii: bool) -> String {
    let quote = if text.contains('\'') && !text.contains('"') { '"' } else { '\'' };
    let mut out = quote.to_string();
    for c in text.chars() {
        match c {
            '\n' => out.push_str("\\n"), '\t' => out.push_str("\\t"), '\r' => out.push_str("\\r"),
            '\\' => out.push_str("\\\\"),
            c if c == quote => { out.push('\\'); out.push(c); }
            c if properties(c) & 32 == 0 || ascii && !c.is_ascii() => {
                let n = c as u32;
                out.push_str(&if n < 256 { format!("\\x{n:02x}") } else if n < 65536 { format!("\\u{n:04x}") } else { format!("\\U{n:08x}") });
            }
            c => out.push(c),
        }
    }
    out.push(quote);
    out
}

pub fn tabs(text: &str, width: usize) -> String {
    let mut out = String::new();
    let mut column = 0;
    for c in text.chars() {
        if c == '\t' {
            let count = if width == 0 { 0 } else { width - column % width };
            out.extend(std::iter::repeat(' ').take(count)); column += count;
        } else {
            out.push(c);
            column = if matches!(c, '\n' | '\r') { 0 } else { column + 1 };
        }
    }
    out
}

pub fn encode(text: &str, ascii: bool, policy: usize) -> Option<Vec<u8>> {
    if !ascii { return Some(text.as_bytes().to_vec()); }
    let mut bytes = Vec::new();
    for c in text.chars() {
        if c.is_ascii() { bytes.push(c as u8); continue; }
        let n = c as u32;
        match policy {
            1 => (),
            2 => bytes.push(b'?'),
            3 => bytes.extend(if n < 256 { format!("\\x{n:02x}") } else if n < 65536 { format!("\\u{n:04x}") } else { format!("\\U{n:08x}") }.bytes()),
            5 => bytes.extend(format!("&#{n};").bytes()),
            _ => return None,
        }
    }
    Some(bytes)
}

pub fn decode(bytes: &[u8], ascii: bool, policy: usize) -> Option<String> {
    let mut out = String::new();
    let mut at = 0;
    while at < bytes.len() {
        let (valid, broken) = if ascii {
            (bytes[at..].iter().position(|b| *b > 127).unwrap_or(bytes.len() - at), 1)
        } else {
            match std::str::from_utf8(&bytes[at..]) {
                Ok(text) => { out.push_str(text); break; }
                Err(e) => (e.valid_up_to(), e.error_len().unwrap_or(bytes.len() - at - e.valid_up_to())),
            }
        };
        out.push_str(std::str::from_utf8(&bytes[at..at + valid]).ok()?);
        at += valid;
        if at == bytes.len() { break; }
        match policy {
            1 => (), 2 => out.push('\u{fffd}'),
            3 => for b in &bytes[at..at + broken] { out.push_str(&format!("\\x{b:02x}")); },
            _ => return None,
        }
        at += broken;
    }
    Some(out)
}

pub fn quoted_points(points: &[u32], ascii: bool) -> String {
    let mark = if points.contains(&39) && !points.contains(&34) { '"' } else { '\'' };
    let mut result = mark.to_string();
    for &n in points {
        if let Some(c) = char::from_u32(n) {
            if c == mark || c == '\\' { result.push('\\'); result.push(c); }
            else if c == '\'' || c == '"' { result.push(c); }
            else {
                let shown = quoted(&c.to_string(), ascii);
                result.push_str(&shown[1..shown.len() - 1]);
            }
        } else { result.push_str(&format!("\\u{n:04x}")); }
    }
    result.push(mark);
    result
}

pub fn escaped_bytes(bytes: &[u8], ascii: bool) -> Vec<u32> {
    let mut row = Vec::new();
    let mut at = 0;
    while at < bytes.len() {
        if ascii { row.push(if bytes[at] < 128 { bytes[at] as u32 } else { 0xdc00 + bytes[at] as u32 }); at += 1; continue; }
        match std::str::from_utf8(&bytes[at..]) {
            Ok(text) => { row.extend(text.chars().map(|c| c as u32)); break; }
            Err(error) => {
                let end = at + error.valid_up_to();
                row.extend(std::str::from_utf8(&bytes[at..end]).expect("the valid prefix").chars().map(|c| c as u32));
                at = end;
                let count = error.error_len().unwrap_or(bytes.len() - at);
                row.extend(bytes[at..at + count].iter().map(|b| 0xdc00 + u32::from(*b)));
                at += count;
            }
        }
    }
    row
}
